#!/usr/bin/python3

"""
    Module defines a metaclass that is used to create VelocityRestClient class.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import os
import json

from velocity_communicator.log.log import Log
from velocity_communicator.core.client_exceptions import FunctionConflict


class CVelocityClientCreator(type):
    """
        Metaclass to fill VelocityRestClient with methods acording to Velocity
        documentation. Also prevents any conflicts with method's name clouding
        each other. Utilizes Singleton Design pattern (there may be only one
        VelocityRestClient class instance used).

        Raises:
            FunctionConflict: when added function have same name as one already
                added.
    """

    _instances = {}
    logger = Log.get_logger('client_creator')

    def __init__(cls, *args):
        services = []
        config_path = os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
            'services'
        )
        for file in os.listdir(config_path):
            if file.endswith(".json"):
                services.append(os.path.join(config_path, file))
        key_list = [a for a in dir(cls) if not a.startswith("__")]
        for file in services:
            with open(file, 'r') as fp:
                try:
                    data = json.load(fp)
                except json.decoder.JSONDecodeError:
                    cls.logger.error(f'JSON format error in {file} file.')
            for key in data:
                if key not in key_list:
                    key_list.append(key)
                    setattr(cls, key, cls._set_function(key, data[key]))
                else:
                    raise FunctionConflict(
                        "Method {} from file {} is in conflict!".format(
                            key, file
                        )
                    )

    def __call__(cls, *args, **kwargs):
        """
            Singleton design pattern.
        """

        if cls not in cls._instances:
            cls._instances[cls] = super(
                CVelocityClientCreator, cls
            ).__call__(*args, **kwargs)
        return cls._instances[cls]

    def _set_function(self, name, body):
        code = """
            def {0}(self, {12}**kwargs):
                import json
                from rest.url_parser import CUrlParser
                url_parameters = {1}
                allowed_filter_keys = {2}
                required_parameters = {3}
                url_args = dict()
                for arg_key in kwargs:
                    if arg_key not in required_parameters:
                        url_args[arg_key] = kwargs[arg_key]
                    if arg_key in url_parameters:
                        url_args[arg_key] = kwargs[arg_key]
                for param in required_parameters:
                    if param in url_parameters:
                        url_args[param] = locals()[param]
                data_out = ''
                try:
                    if body:
                        try:
                            if 'application/zip' in '{10}':
                                data_out = body
                            elif "tbml" in body:
                                data_out = body
                            elif 'text/csv' in '{10}':
                                data_out = body
                            else:
                                data_out = json.dumps(body)
                        except ValueError:  # it's not json
                            data_out = body
                except NameError:  # No body in args, pass
                    pass
                url_parser = CUrlParser(
                    {4}, url_args, allowed_filter_keys,
                    pageable={5}, sortable={6}, filterable={7}
                )
                response = self.query(
                    url_parser, query_type="{8}", result={9},
                    data=data_out, content_type='{10}', accept_type='{11}'
                )
                return response
        """.format(
            name, body['url_parameters'], body['allowed_filter_keys'],
            body['required_parameters'], body['url'], body['pageable'],
            body['sortable'], body['filterable'], body['query_type'],
            body['result'], body['content_type'], body['accept_type'],
            ', '.join(body['required_parameters'] + [' '])
        )
        code_dict = {}
        exec(code.strip(), code_dict)
        return code_dict[name]
